     1→import Database from 'better-sqlite3';
     2→import path from 'path';
     3→import fs from 'fs';
     4→
     5→const DB_PATH = path.join(process.cwd(), 'database', 'sangsi.db');
     6→const SCHEMA_PATH = path.join(process.cwd(), 'database', 'schema.sql');
     7→
     8→let _db: Database.Database | null = null;
     9→
    10→export function getDb(): Database.Database {
    11→  if (_db) return _db;
    12→
    13→  const dbDir = path.dirname(DB_PATH);
    14→  if (!fs.existsSync(dbDir)) {
    15→    fs.mkdirSync(dbDir, { recursive: true });
    16→  }
    17→
    18→  _db = new Database(DB_PATH);
    19→  _db.pragma('journal_mode = WAL');
    20→  _db.pragma('foreign_keys = ON');
    21→
    22→  const schema = fs.readFileSync(SCHEMA_PATH, 'utf-8');
    23→  _db.exec(schema);
    24→
    25→  return _db;
    26→}
    27→
    28→export default getDb;
    29→

